{
  "findings": [
    {
      "check_id": "CKV_AZURE_59",
      "title": "Storage account permits public network access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not disable its public network endpoint, allowing traffic to reach it over the public internet."
    },
    {
      "check_id": "CKV_AZURE_33",
      "title": "Queue service logging is not enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "No Queue Storage logging configuration records read, write, and delete operations, reducing visibility into unauthorized or destructive activity."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Storage account permits obsolete TLS",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The minimum TLS version is explicitly set to TLS 1.0, which is obsolete and vulnerable to known cryptographic weaknesses."
    },
    {
      "check_id": "CKV_AZURE_3",
      "title": "HTTPS-only traffic is disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account explicitly permits non-HTTPS traffic, which can expose storage data and authentication material in transit."
    },
    {
      "check_id": "CKV_AZURE_190",
      "title": "Blob public access is not restricted",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account does not explicitly prohibit nested blob containers and objects from being configured for public access."
    },
    {
      "check_id": "CKV2_AZURE_40",
      "title": "Shared Key authorization is enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Shared Key authorization is not disabled, allowing long-lived account keys to bypass identity-based Azure RBAC controls."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Anonymous blob access is not disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account lacks an explicit prohibition on anonymous access to nested blob resources."
    },
    {
      "check_id": "CKV2_AZURE_33",
      "title": "Storage account has no private endpoint",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "No private endpoint is configured for the storage account, so blob access is not anchored to a private virtual network path."
    },
    {
      "check_id": "CKV2_AZURE_41",
      "title": "SAS expiration policy is missing",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account has no SAS expiration policy to constrain the lifetime of issued shared access signatures."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Storage soft delete is not enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Blob and container soft-delete retention are absent, increasing the risk of permanent data loss following accidental or malicious deletion."
    }
  ],
  "patched_code": "variable \"private_endpoint_subnet_id\" {\n  description = \"Resource ID of the subnet used by the storage account private endpoint.\"\n  type        = string\n}\n\nresource \"azurerm_storage_account\" \"media_storage\" {\n  name                          = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name           = azurerm_resource_group.corporate_media_streaming.name\n  location                      = azurerm_resource_group.corporate_media_streaming.location\n  account_tier                  = \"Standard\"\n  account_replication_type      = \"GRS\"\n  enable_https_traffic_only     = true\n  min_tls_version               = \"TLS1_2\"\n  public_network_access_enabled = false\n  allow_nested_items_to_be_public = false\n  shared_access_key_enabled     = false\n\n  sas_policy {\n    expiration_period = \"7.00:00:00\"\n    expiration_action = \"Log\"\n  }\n\n  blob_properties {\n    versioning_enabled = true\n\n    delete_retention_policy {\n      days = 7\n    }\n\n    container_delete_retention_policy {\n      days = 7\n    }\n  }\n\n  queue_properties {\n    logging {\n      delete                = true\n      read                  = true\n      write                 = true\n      version               = \"1.0\"\n      retention_policy_days = 7\n    }\n  }\n}\n\nresource \"azurerm_private_endpoint\" \"media_storage_blob\" {\n  name                = \"${azurerm_storage_account.media_storage.name}-blob-pe\"\n  location            = azurerm_resource_group.corporate_media_streaming.location\n  resource_group_name = azurerm_resource_group.corporate_media_streaming.name\n  subnet_id           = var.private_endpoint_subnet_id\n\n  private_service_connection {\n    name                           = \"${azurerm_storage_account.media_storage.name}-blob-psc\"\n    private_connection_resource_id = azurerm_storage_account.media_storage.id\n    subresource_names              = [\"blob\"]\n    is_manual_connection           = false\n  }\n}\n",
  "fix_summary": "Enforced HTTPS with TLS 1.2, disabled public and Shared Key access, added SAS expiry, Queue logging, and blob/container soft delete. Public network access is disabled and a subnet-configurable private endpoint was added for the blob service."
}
